// computed from the UNFILTERED day: derived from the filtered rows, the filter
// control would collapse to the single option already chosen and there would be
// no way back to the others.
func (q *Queries) ListPublicDayCategories(ctx context.Context, odDate pgtype.Date) ([]ListPublicDayCategoriesRow, error) {
	rows, err := q.db.Query(ctx, listPublicDayCategories, odDate)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListPublicDayCategoriesRow
	for rows.Next() {
		var i ListPublicDayCategoriesRow
		if err := rows.Scan(&i.ID, &i.Name); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listPublicDayODRecords = `-- name: ListPublicDayODRecords :many
SELECT
    s.roll_no,
    s.name       AS student_name,
    r.slot,
    c.id         AS category_id,
    c.name       AS category_name,
    e.name       AS event_name
FROM od_records r
JOIN students s ON s.id = r.student_id
JOIN categories c ON c.id = r.category_id
JOIN events e ON e.id = r.event_id
WHERE r.od_date = $1
  AND r.status = 'present'
  AND ($2::integer IS NULL OR r.slot = $2)
  AND ($3::uuid IS NULL OR r.category_id = $3)
ORDER BY s.roll_no ASC, r.slot ASC, c.name ASC
LIMIT $4::bigint
`

type ListPublicDayODRecordsParams struct {
	OdDate     pgtype.Date `json:"od_date"`
	Slot       pgtype.Int4 `json:"slot"`
	CategoryID pgtype.UUID `json:"category_id"`
	RowLimit   int64       `json:"row_limit"`
}

type ListPublicDayODRecordsRow struct {
	RollNo       string      `json:"roll_no"`
	StudentName  string      `json:"student_name"`
	Slot         int32       `json:"slot"`
	CategoryID   pgtype.UUID `json:"category_id"`
	CategoryName string      `json:"category_name"`
	EventName    string      `json:"event_name"`
}

// One campus day's present OD records, for the UNAUTHENTICATED public board.
//
// THE SELECT LIST IS THE SECURITY BOUNDARY. This result is serialised to the
// open internet with no credential, so it is a separate query from
// ListAttendanceRecords rather than that query with a viewer of NULL — even
// though the joins and the day/slot/category predicates are the same shape. The
// authenticated one selects users.email, actor_user_id, capture_method and
// reason_note, and reason_note is a teacher's free-text justification for a
// correction ("removed, the student was not actually present"). Sharing the
// query would mean the next column added for administrators becomes public on
// the day it is added, with nothing failing. Duplicating five join lines is the
// cheaper mistake.
//
// status = 'present' is NOT optional here. The admin view deliberately shows
// removed rows; a public board that did would show a student as marked after a
// teacher had removed the record, which is worse than showing nothing at all.
//
// NO events.status FILTER, for the same reason ListPublicStudentODRecords has
// none (T6): archiving is an administrative act on the event, not a retraction
// of attendance.
//
// Ordered by roll number so the board is scannable by the thing a student looks
// for first, then by slot so one student's marks read 6, 7, 10 in that order.
//
// row_limit is a server-chosen ceiling, and the caller cannot raise it: a limit
// the open internet controls is a limit that gets set to 10,000. The service
// reads one row past the cap to tell "exactly full" from "truncated".
func (q *Queries) ListPublicDayODRecords(ctx context.Context, arg ListPublicDayODRecordsParams) ([]ListPublicDayODRecordsRow, error) {
	rows, err := q.db.Query(ctx, listPublicDayODRecords,
		arg.OdDate,
		arg.Slot,
		arg.CategoryID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListPublicDayODRecordsRow
	for rows.Next() {
		var i ListPublicDayODRecordsRow
		if err := rows.Scan(
			&i.RollNo,
			&i.StudentName,
			&i.Slot,
			&i.CategoryID,
			&i.CategoryName,
			&i.EventName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listPublicStudentODRecords = `-- name: ListPublicStudentODRecords :many
SELECT
    r.id,
    r.slot,
    r.event_id,
    e.name       AS event_name,
    e.event_date AS event_date,
    r.od_date    AS od_date,
    c.id         AS category_id,
    c.name       AS category_name,
    u.name       AS marked_by_name,
    r.actor_role AS marked_by_role,
    r.server_received_at
FROM od_records r
JOIN events e ON e.id = r.event_id
JOIN categories c ON c.id = r.category_id
LEFT JOIN users u ON u.id = r.actor_user_id
WHERE r.student_id = $1
  AND r.status = 'present'
ORDER BY r.od_date DESC, r.slot ASC, r.server_received_at ASC, r.id ASC
LIMIT $2::bigint
`

type ListPublicStudentODRecordsParams struct {
	StudentID pgtype.UUID `json:"student_id"`
	RowLimit  int64       `json:"row_limit"`
}

type ListPublicStudentODRecordsRow struct {
	ID               pgtype.UUID        `json:"id"`
	Slot             int32              `json:"slot"`
	EventID          pgtype.UUID        `json:"event_id"`
	EventName        string             `json:"event_name"`
	EventDate        pgtype.Date        `json:"event_date"`
	OdDate           pgtype.Date        `json:"od_date"`
	CategoryID       pgtype.UUID        `json:"category_id"`
	CategoryName     string             `json:"category_name"`
	MarkedByName     pgtype.Text        `json:"marked_by_name"`
	MarkedByRole     string             `json:"marked_by_role"`
	ServerReceivedAt pgtype.Timestamptz `json:"server_received_at"`
}

// One student's present OD records for the UNAUTHENTICATED public dashboard
// (Story 0.10, FR39).
//
// GROUPING KEY IS od_records.od_date, NOT server_received_at and no longer
// events.event_date. An event spans a range of days, so the event's first day
// would collapse a thirty-day festival onto one heading; and deriving the day
// from the receipt time would file a teacher's next-morning correction under the
// wrong day, which on this screen reads to the student as "I was not marked".
// od_date is the day the OD belongs to, which is the only one of the three that
// is the fact this screen is about.
//
// e.event_date is STILL selected alongside it: the record's event_date is the
// event's first day, and the dispute form's event options are built from it.
//
// NO events.status FILTER, deliberately (T6). Archiving is an administrative act
// on the event, not a retraction of the student's attendance; filtering active
// events here would erase a student's whole record the moment a coordinator
// tidied up after the event — exactly when they are most likely to check it.
//
// LEFT JOIN users because actor_user_id is ON DELETE SET NULL. An inner join
// would silently delete a student's attendance record as a side effect of
// off-boarding a teacher. actor_role is read from the RECORD, not the user row,
// so the role survives the actor.
//
// Selects display columns only: no users.email, no actor id, and
// student_card_tokens is never joined. This result is serialised to the open
// internet.
//
// od_records_student_event_slot_idx leads with student_id, which is this
// query's only equality predicate — no new index is needed.
//
// row_limit is a server-chosen ceiling rather than a page parameter: pagination
// cannot be reconciled with day grouping without splitting a day across pages,
// and 12 slots a day makes any realistic history far smaller than the cap.
func (q *Queries) ListPublicStudentODRecords(ctx context.Context, arg ListPublicStudentODRecordsParams) ([]ListPublicStudentODRecordsRow, error) {
	rows, err := q.db.Query(ctx, listPublicStudentODRecords, arg.StudentID, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListPublicStudentODRecordsRow
	for rows.Next() {
		var i ListPublicStudentODRecordsRow
		if err := rows.Scan(
			&i.ID,
			&i.Slot,
			&i.EventID,
			&i.EventName,
			&i.EventDate,
			&i.OdDate,
			&i.CategoryID,
			&i.CategoryName,
			&i.MarkedByName,
			&i.MarkedByRole,
			&i.ServerReceivedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

